import React from "react";

function JobStats({ jobs }) {
  const stats = [
    { label: "Total Jobs", value: jobs.length },
    {
      label: "Full-time Positions",
      value: jobs.filter((j) => j.jobType === "Full-time").length,
    },
    {
      label: "Part-time Positions",
      value: jobs.filter((j) => j.jobType === "Part-time").length,
    },
  ];

  const styles = {
    grid: { display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(250px,1fr))", gap: "25px", marginBottom: "35px" },
    card: { background: "#fff", borderRadius: "12px", padding: "25px 30px", textAlign: "center", boxShadow: "0 2px 12px rgba(0,0,0,0.05)" },
    label: { fontSize: "15px", color: "#6b7280", marginBottom: "8px" },
    value: { fontSize: "28px", fontWeight: "600", color: "#1e40af" },
  };

  return (
    <div style={styles.grid}>
      {stats.map((stat, i) => (
        <div key={i} style={styles.card}>
          <h3 style={styles.label}>{stat.label}</h3>
          <div style={styles.value}>{stat.value}</div>
        </div>
      ))}
    </div>
  );
}

export default JobStats;
